func validateReceiptFile(filePath string) error {
	info, err := os.Stat(filePath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("file %q does not exist", filePath)
		}
		return fmt.Errorf("error stating file %q: %w", filePath, err)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("path %q is not a regular file", filePath)
	}
	if info.Size() == 0 {
		return fmt.Errorf("file %q is empty", filePath)
	}
	const maxBytes = 20 * 1024 * 1024 // 20 MB
	if info.Size() > maxBytes {
		return fmt.Errorf("file %q size (%.2f MB) exceeds maximum allowed size of 20 MB", filePath, float64(info.Size())/(1024*1024))
	}
	ext := strings.ToLower(filepath.Ext(filePath))
	validExts := map[string]bool{
		".png":  true,
		".jpg":  true,
		".jpeg": true,
		".pdf":  true,
		".tif":  true,
		".tiff": true,
	}
	if !validExts[ext] {
		return fmt.Errorf("unsupported file extension %q: must be one of .png, .jpg, .jpeg, .pdf, .tif, .tiff", ext)
	}
	return nil
}
